from lib import *
from fractions import Fraction as F
LESSON = 'ភាគរយ'
def pc(x):
    x = F(x)
    s = f'{float(x):.4f}'.rstrip('0').rstrip('.')
    return s + '\\%'
def R(n): return M(num(n)) + ' ៛'
def W(ans, cand, k=3, fmt=None):
    fmt = fmt or (lambda v: M(pc(v)))
    out = []
    for c in cand:
        c = F(c)
        if c != ans and c not in out: out.append(c)
    d = 1
    while len(out) < k:
        c = F(ans) + d * (1 if d % 2 else -1) * (F(ans).denominator and 5); d += 1
        if c != ans and c not in out and c > 0: out.append(c)
    return [fmt(c) for c in out[:k]]
def Wr(ans, cand, k=3): return W(F(ans), cand, k, lambda v: R(int(v)))

